# List all files in the state directory to understand structure
import os

state_base = '/home/USER/runs/paper/qwen-h-u1-turns/frozen/held-out/play/users/u089/system/state'

def find_json_files(base_dir, max_depth=3):
    results = []
    for root, dirs, files in os.walk(base_dir):
        depth = root.replace(base_dir, '').count(os.sep)
        if depth < max_depth:
            for f in files:
                if f.endswith('.json'):
                    # Get relative path from base_dir
                    rel_path = os.path.join(root, f)
                    results.append(rel_path)
    return results

json_files = find_json_files(state_base)
print(f"Found {len(json_files)} JSON files in state directory")
print("\nFiles:")
for f in json_files[:30]:
    print(f"  {os.path.relpath(f, state_base)}")

